// Calibrated overlay is generated by the original stip_thermal_camera ROS node.
// Warm it when the popup opens; switching later changes the displayed stream,
// never reprojects/warps thermal in JavaScript.
function openExpandedCamera(){
    if(state.page!=='patrol' || state.mode!=='live')return;
    state.expandedCameraOpen=true;
    const smallRGB=$('#liveCamera'),smallThermal=$('#liveThermal');
    if(smallRGB)smallRGB.removeAttribute('src');
    if(smallThermal)smallThermal.removeAttribute('src');
    modal('Live Inspection Camera',`
        <div class="expanded-camera-controls">
          <label><input type="checkbox" id="expandedThermalToggle" onchange="setExpandedThermal(this.checked)"> Calibrated thermal overlay</label>
          <span id="registeredOverlayStatus" class="small muted">RGB live · thermal uses saved ROS alignment</span>
          <button class="btn s" type="button" onclick="closeExpandedCamera()">× Close</button>
        </div>
        <div class="expanded-camera-stage">
          <img id="expandedRGB" src="/api/camera.mjpg" alt="Live RGB camera">
          <svg id="expandedCameraOverlay" class="inspection-overlay" preserveAspectRatio="xMidYMid meet" aria-label="Live ROS QR and fire detections"></svg>
        </div>
        <p class="small muted">Thermal overlay is rendered by stip_thermal_camera using thermal_rgb_alignment.yaml. Registration is valid near calibration depth; it does not compensate for parallax.</p>`);
    const root=$('#modalBackdrop');if(root)root.classList.add('expanded-camera-dialog');
    updatePatrolInspection();
    // Start calibrated ROS registration early, while the operator sees normal
    // live RGB. Reuse the node during this Patrol session instead of repeatedly
    // launching it with every checkbox click.
    warmRegisteredOverlay();
}
let registeredOverlayPromise=null, registeredOverlayReady=false;
function warmRegisteredOverlay(){
    if(registeredOverlayReady)return Promise.resolve(true);
    if(registeredOverlayPromise)return registeredOverlayPromise;
    registeredOverlayPromise=(async function(){
        await act('thermal_overlay_start',{},7000);
        // Use native ROS output only after the first REAL calibrated frame.
        for(let i=0;i<25;i++){
            await new Promise(resolve=>setTimeout(resolve,240));
            const r=await get('overlay_status');
            if(r.ready){registeredOverlayReady=true;return true;}
        }
        throw Error('No calibrated /thermal/rgb_overlay frames. Check ROS alignment node and thermal sensor.');
    })();
    registeredOverlayPromise.catch(e=>{
        // Do not show a toast before the user has even requested thermal.
        const status=$('#registeredOverlayStatus');if(status)status.textContent='Overlay unavailable: '+e.message;
    }).finally(()=>{registeredOverlayPromise=null;});
    return registeredOverlayPromise;
}
async function setExpandedThermal(on){
    const image=$('#expandedRGB'),status=$('#registeredOverlayStatus'),toggle=$('#expandedThermalToggle');
    if(!image || !status)return;
    if(!on){
        if(image.getAttribute('src')!=='/api/camera.mjpg')image.src='/api/camera.mjpg';
        status.textContent='RGB live · registered overlay ready: '+(registeredOverlayReady?'yes':'warming');
        return;
    }
    status.textContent=registeredOverlayReady?'Switching calibrated stream…':'Preparing calibrated ROS overlay…';
    if(toggle)toggle.disabled=true;
    try{
        await warmRegisteredOverlay();
        if(!state.expandedCameraOpen || !toggle || !toggle.checked)return;
        image.src='/api/camera_registered.mjpg';
        status.textContent='Calibrated RGB + thermal · ROS registration';
    }catch(e){
        if(toggle)toggle.checked=false;
        status.textContent='Calibrated overlay unavailable';
        toast(e.message,true);
    }finally{if(toggle)toggle.disabled=false;}
}
function closeExpandedCamera(){closeModal();}

function restorePatrolCameraPreviews(){
    if(!state.expandedCameraOpen)return;
    state.expandedCameraOpen=false;
    // Keep the already-warmed, dashboard-owned overlay node available until
    // Patrol exit. The server owns its shutdown when the session ends.
    const rgb=$('#liveCamera'),thermal=$('#liveThermal');
    if(rgb)rgb.src='/api/camera.mjpg';
    if(thermal)thermal.src='/api/thermal.mjpg';
}
